'use strict';

const { ExprError } = require('./errors');

const PAIRS = new Set(['**', '//', '<=', '>=', '==', '!=']);
const SINGLES = new Set(['+', '-', '*', '/', '%', '<', '>', '(', ')', ',']);

/**
 * Return a function producing the next positioned token on each call. Tokens are
 * lexed on demand, so an invalid character is only reported once the parser
 * reaches it (after any earlier syntax error).
 */
function createLexer(source) {
  const whitespace = /\s*/y;
  const number = /(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?/y;
  const identifier = /[A-Za-z_][A-Za-z0-9_]*/y;
  let offset = 0;
  return function next() {
    whitespace.lastIndex = offset;
    whitespace.exec(source);
    offset = whitespace.lastIndex;
    if (offset >= source.length) return { type: 'eof', value: '', column: source.length + 1 };
    const column = offset + 1;
    number.lastIndex = offset;
    const numeric = number.exec(source);
    if (numeric) {
      offset = number.lastIndex;
      return { type: 'number', value: Number(numeric[0]), column };
    }
    identifier.lastIndex = offset;
    const name = identifier.exec(source);
    if (name) {
      offset = identifier.lastIndex;
      return { type: 'identifier', value: name[0], column };
    }
    const pair = source.slice(offset, offset + 2);
    if (PAIRS.has(pair)) {
      offset += 2;
      return { type: 'operator', value: pair, column };
    }
    if (SINGLES.has(source[offset])) {
      offset += 1;
      return { type: 'operator', value: source[offset - 1], column };
    }
    throw new ExprError('Unexpected character', column);
  };
}

module.exports = { createLexer };

'use strict';

const { ExprError } = require('./errors');
const { createLexer } = require('./tokenizer');

const COMPARISONS = new Set(['<', '<=', '>', '>=', '==', '!=']);
const PRODUCTS = new Set(['*', '/', '//', '%']);
const FUNCTIONS = new Set(['min', 'max', 'abs']);

/** Parse a complete source string into an AST. Nodes retain operator columns. */
function parse(source) {
  const next = createLexer(source);
  let lookahead = null;
  const current = () => lookahead || (lookahead = next());
  const take = () => {
    const token = current();
    lookahead = null;
    return token;
  };
  const isOperator = value => current().type === 'operator' && current().value === value;
  const inSet = set => current().type === 'operator' && set.has(current().value);
  const expect = value => {
    if (!isOperator(value)) throw new ExprError(`Expected ${value}`, current().column);
    return take();
  };
  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });

  function comparison() {
    const first = sum();
    if (!inSet(COMPARISONS)) return first;
    const operands = [first];
    const operators = [];
    while (inSet(COMPARISONS)) {
      operators.push(take());
      operands.push(sum());
    }
    return { type: 'comparison', operands, operators };
  }

  function sum() {
    let left = product();
    while (isOperator('+') || isOperator('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  function product() {
    let left = unary();
    while (inSet(PRODUCTS)) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  function unary() {
    const signs = [];
    while (isOperator('+') || isOperator('-')) signs.push(take());
    let node = power();
    for (let i = signs.length - 1; i >= 0; i -= 1) {
      node = { type: 'unary', operator: signs[i], operand: node };
    }
    return node;
  }

  function power() {
    const base = primary();
    if (!isOperator('**')) return base;
    const operator = take();
    return binary(operator, base, unary());
  }

  function primary() {
    const token = take();
    if (token.type === 'number') return { type: 'number', value: token.value };
    if (token.type === 'identifier') {
      if (!isOperator('(')) return { type: 'variable', name: token.value, column: token.column };
      if (!FUNCTIONS.has(token.value)) throw new ExprError('Unknown function', token.column);
      take();
      if (isOperator(')')) throw new ExprError('Wrong argument count', token.column);
      const args = [comparison()];
      while (isOperator(',')) {
        if (token.value === 'abs') throw new ExprError('Wrong argument count', token.column);
        take();
        args.push(comparison());
      }
      expect(')');
      return { type: 'call', name: token.value, args };
    }
    if (token.type === 'operator' && token.value === '(') {
      const expression = comparison();
      expect(')');
      return expression;
    }
    throw new ExprError('Expected an expression', token.column);
  }

  const expression = comparison();
  if (current().type !== 'eof') throw new ExprError('Unexpected token', current().column);
  return expression;
}

module.exports = { parse };

